            completeFunc: ffi_forge_ffi_rust_future_complete_pointer,
            freeFunc: ffi_forge_ffi_rust_future_free_pointer,
            liftFunc: FfiConverterTypeForgeCounterApp.lift,
            errorHandler: FfiConverterTypeForgeAppError.lift
